func NewCellAssistanceInformationUnknownExtension(index uint64, contents []byte, options ...aper.BuildOption) (CellAssistanceInformation, error) {
	budget, err := aper.BuildBudget(options...)
	if err != nil {
		return CellAssistanceInformation{}, aper.OperationError(err, "CellAssistanceInformationUnknownExtension")
	}
	extension, err := aper.BuildChoiceExtension(index, contents, budget)
	if err != nil {
		return CellAssistanceInformation{}, aper.OperationError(err, "CellAssistanceInformationUnknownExtension")
	}
	value := CellAssistanceInformation{UnknownExtension: &extension}
	if _, err := X2apInternalCellAssistanceInformationMarshalAPERBudget(&value, budget, false); err != nil {
		return CellAssistanceInformation{}, aper.OperationError(err, "CellAssistanceInformationUnknownExtension")
	}
	return value, aper.OperationError(nil, "CellAssistanceInformationUnknownExtension")
}
